import sys

def sieve(n: int):
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    p = 2
    while p * p <= n:
        if is_prime[p]:
            step = p
            start = p * p
            is_prime[start:n + 1:step] = [False] * (((n - start) // step) + 1)
        p += 1
    return is_prime

